INSERT INTO config (chave, valor) VALUES ('midia_brio', '[{"id": "18078339506774571", "ts": "2026-11-12T15:35:36+0000", "link": "https://www.instagram.com/reel/DfpXXxboTjj/", "cap": "Você faz abdominal todo dia pra secar a barriga? Isso quase não mexe na gordura dali. 👇\nTi"}, {"id": "17954743470270527", "ts": "2026-11-12T09:20:36+0000", "link": "https://www.instagram.com/reel/DfouDQVJKN5/", "cap": "Você treina pesado e não cresce? Talvez o problema esteja fora da academia. 👇\nComenta SONO"}, {"id": "18012255083782169", "ts": "2026-11-11T21:04:48+0000", "link": "https://www.instagram.com/reel/DfnZhbwh7UZ/", "cap": "Treinar em jejum queima mais gordura? Muita gente acorda cedo e vai sem comer por causa di"}, {"id": "18134781724683773", "ts": "2026-11-11T15:26:12+0000", "link": "https://www.instagram.com/reel/DfmzIXXpJu2/", "cap": "Treina há um ano e o shape não mudou nada? Calma. Não é genética.\n\nSalva pro próximo trein"}, {"id": "18354174583267361", "ts": "2026-11-11T09:59:45+0000", "link": "https://www.instagram.com/reel/DfmNv0Vp0LB/", "cap": "Ficou duas semanas sem treinar e acha que perdeu tudo? Calma, a conta é outra. 👇\nManda pro"}, {"id": "18134081170757751", "ts": "2026-11-11T01:59:06+0000", "link": "https://www.instagram.com/reel/DflWvfQgRPp/", "cap": "Creatina engorda, dá retenção e precisa ciclar? Vamos separar o mito da verdade. 👇\nTime cr"}, {"id": "18106414190368375", "ts": "2026-11-11T00:46:08+0000", "link": "https://www.instagram.com/reel/DflOZ6mAWof/", "cap": "Trinta dias de academia. O que muda de verdade no seu corpo? Vou te mostrar dia por dia. 👇"}, {"id": "18122297048061109", "ts": "2026-11-10T21:05:00+0000", "link": "https://www.instagram.com/reel/Dfk1G9CpYCZ/", "cap": "Você vai até a falha em toda série? Isso pode estar te atrasando. 👇\n\n#brio #academia #hipe"}, {"id": "18134068225815533", "ts": "2026-11-10T18:31:50+0000", "link": "https://www.instagram.com/p/DfkjnGWpZ_s/", "cap": "3 sinais de que está na hora de aumentar a carga\n#brio\n#academia\n#musculacao\n#progressaode"}, {"id": "18135832370498080", "ts": "2026-11-10T15:08:54+0000", "link": "https://www.instagram.com/reel/DfkMV7fJ2VI/", "cap": "Treinar o mesmo músculo todo dia faz crescer mais rápido? Não é bem assim. 👇\n\n#brio #hiper"}, {"id": "17998443072057476", "ts": "2026-11-10T12:48:29+0000", "link": "https://www.instagram.com/p/Dfj8Ur4p-nc/", "cap": "Treino bom não é o mais difícil. É o que cabe na sua rotina.\n\nO BRIO organiza seu plano, m"}, {"id": "18155918479536541", "ts": "2026-11-10T10:00:13+0000", "link": "https://www.instagram.com/reel/DfjpBanpIaG/", "cap": "Seu ombro não cresce? Talvez você esteja fazendo a elevação lateral errado. 👇\n\n#brio #acad"}, {"id": "18048250979824595", "ts": "2026-11-10T00:59:42+0000", "link": "https://www.instagram.com/reel/DfirLZRg4_1/", "cap": "Você coloca peso pra impressionar? O ego tá roubando o seu músculo. 👇\n\n#brio #academia #mu"}, {"id": "17967607907980549", "ts": "2026-11-09T23:29:15+0000", "link": "https://www.instagram.com/reel/DfigsULgd5y/", "cap": "Seja sincero: você descansa entre as séries, ou some no celular? 👇\n\n#brio #academia #muscu"}, {"id": "18201143728343413", "ts": "2026-11-09T21:21:09+0000", "link": "https://www.instagram.com/reel/DfiRfdlpraa/", "cap": "Você sobe a carga no chute? Tem uma regra simples, e quase ninguém usa. 👇\n\n#brio #academia"}, {"id": "18135122257744451", "ts": "2026-11-09T15:01:27+0000", "link": "https://www.instagram.com/reel/DfhmtT-JM1M/", "cap": "Você vai até a falha em toda série? Isso pode estar te atrasando. 👇\n\n#brio #academia #hipe"}, {"id": "18451352842130920", "ts": "2026-11-09T10:00:57+0000", "link": "https://www.instagram.com/reel/DfhEUDyJbAo/", "cap": "Quanto tempo leva pra ver resultado na academia? A resposta vai te poupar muita frustração"}, {"id": "17919393384260471", "ts": "2026-11-08T21:27:01+0000", "link": "https://www.instagram.com/reel/DffuChypudk/", "cap": "#brio #academia #musculacao #dormuscular #mitosdaacademia"}, {"id": "18133262038683807", "ts": "2026-10-25T23:28:09+0000", "link": "https://www.instagram.com/p/De74jzGJT2_/", "cap": "#TreineComBRIO #MeuTreinoBRIO #EvoluaComBRIO #BRIOFitness TimeBRIO BRIO BRIOTreino TreinoI"}, {"id": "17912704887550501", "ts": "2026-10-24T17:12:29+0000", "link": "https://www.instagram.com/p/De4pBa3JqER/", "cap": ""}, {"id": "17898898755397291", "ts": "2026-10-24T17:12:21+0000", "link": "https://www.instagram.com/p/De4pAcQpBh9/", "cap": ""}, {"id": "17913090528515868", "ts": "2026-10-24T17:12:10+0000", "link": "https://www.instagram.com/p/De4o-sfpORH/", "cap": ""}]') ON CONFLICT(chave) DO UPDATE SET valor=excluded.valor, atualizado_em=datetime('now');
